const D = require('../../src/lib/domain.cjs');
const {month, uid, ORIGINS, DESTINATIONS, repairContactOrigins, reconcile} = D;
function seed(){const now=new Date(),past=month(new Date(now.getFullYear(),now.getMonth()-3,1,12)),names=['Helena Carvalho','Rafael Mendes','Ana Beatriz Lima','Instituto Girassol','João Pedro Santos','Mariana Oliveira','Padaria Pão da Vila','Clara Fernandes','Lucas Almeida','Patrícia Costa','Daniel Rocha','Fernanda Ribeiro','Farmácia Bem Viver','Isabela Martins','Pedro Henrique','Juliana Sousa','Carlos Eduardo','Renata Araújo','Sofia Nascimento','Gabriel Silva','Camila Barros','Eduardo Pereira','Livraria Caminhos','Luiza Torres'];const s={version:1,users:[],contacts:[],payments:[],lists:[],campaigns:[],audit:[],tasks:[],resets:[]},a={id:'admin',name:'Marina Costa'};names.forEach((name,i)=>{const created=new Date(now.getFullYear(),now.getMonth()-(i<8?3:0),Math.min(i+1,now.getDate()),9).toISOString(),c={id:'contact-'+i,name,email:'contato'+(i+1)+'@exemplo.com',phone:'869'+String(81000000+i),document:'',type:[3,6,12,22].includes(i)?'PJ':'PF',origin:ORIGINS[i%6],funnel:['Site','Instagram'].includes(ORIGINS[i%6])?'Inbound':i%3===0?'Outbound':'Inbound',stage:i<8?3:i%4,owner:i%3===0?'operator':'admin',created,optOut:i===22,history:[]};if(i<8)c.plan={mode:i===5?'Pontual':'Recorrente',amount:[150,100,80,500,120,250,300,100][i],due:[5,10,15,5,20,10,10,28][i],since:past,status:i===7?'Pausado':'Ativo'};c.history.push({id:uid(),at:created,actor:a.id,actorName:a.name,action:'Contato cadastrado',details:c.origin+' · '+c.funnel});s.contacts.push(c);if(i===7||i>=8)return;for(let offset=-3;offset<=0;offset++){if((i===2&&offset>=-2)||(i===4&&offset===0)||(i===5&&offset!==0))continue;const date=month(new Date(now.getFullYear(),now.getMonth()+offset,1,12))+'-'+String(Math.min(2,now.getDate())).padStart(2,'0');s.payments.push({id:uid(),contactId:c.id,amount:c.plan.amount,date,period:month(date),mode:c.plan.mode,pix:'PIX-DEMO-'+i+'-'+offset,destination:DESTINATIONS[i%4],attachment:null,at:date+'T12:00:00Z',actor:a.id,actorName:a.name,receipt:'LUZ-'+String(s.payments.length+1).padStart(5,'0')})}});s.payments.forEach(p=>{const c=s.contacts.find(c=>c.id===p.contactId),e={id:uid(),at:p.at,actor:p.actor,actorName:p.actorName,action:'Doação recebida',contactId:c.id,details:'R$ '+p.amount.toFixed(2)+' · '+p.destination+' · '+p.receipt};c.history.push(e);s.audit.push(e)});s.contacts.filter(c=>c.plan).forEach(c=>c.history.push({id:uid(),at:c.created,actor:'admin',actorName:a.name,action:'Conversão em doador',details:c.plan.mode+' · R$ '+c.plan.amount.toFixed(2)}));s.contacts.forEach(c=>c.history.sort((x,y)=>y.at.localeCompare(x.at)));s.audit.sort((x,y)=>y.at.localeCompare(x.at));s.lists=[{id:'list-1',name:'Comércio de Parnaíba',category:'Empresas locais',description:'Negócios da comunidade que podem caminhar conosco.',contacts:['contact-3','contact-6','contact-12','contact-22'],imports:[]},{id:'list-2',name:'Amigos da Esperança',category:'Pessoas físicas',description:'Pessoas que conheceram nossas obras sociais.',contacts:['contact-8','contact-9','contact-14','contact-18'],imports:[]}];repairContactOrigins(s);reconcile(s,{id:'system',name:'Sistema'});return s}
